// scratch3: diff-tree flags + update-index three-arg cacheinfo + reset --hard equivalence
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

function run(cwd: string, args: string[], stdin?: Buffer, env: Record<string, string> = {}) {
  const r = Bun.spawnSync(["git", ...args], {
    cwd,
    stdin: stdin ?? "ignore",
    stdout: "pipe",
    stderr: "pipe",
    env: { ...process.env, ...env },
  });
  return { code: r.exitCode, out: r.stdout.toString(), err: r.stderr.toString() };
}
function ok(cwd: string, args: string[], stdin?: Buffer, env?: Record<string, string>) {
  const r = run(cwd, args, stdin, env);
  if (r.code !== 0) throw new Error(`git ${args.join(" ")}: ${r.err}`);
  return r.out;
}

const base = mkdtempSync(join(tmpdir(), "f10scratch3-"));
const src = join(base, "src");
mkdirSync(src);
ok(src, ["init", "-q", "-b", "main"]);
ok(src, ["config", "user.email", "[REDACTED_EMAIL]"]);
ok(src, ["config", "user.name", "T"]);
writeFileSync(join(src, "f.txt"), "a < b\n");
ok(src, ["add", "-A"]);
ok(src, ["commit", "-qm", "c1"]);
const c1 = ok(src, ["rev-parse", "HEAD"]).trim();
writeFileSync(join(src, "f.txt"), "a < b\nc > d\n");
ok(src, ["add", "-A"]);
ok(src, ["commit", "-qm", "c2"]);
const c2 = ok(src, ["rev-parse", "HEAD"]).trim();

const out = join(base, "copy");
ok(base, ["clone", "--no-local", src, out]);

const FLAGS = ["diff-tree", "-r", "-m", "--first-parent", "--root", "--no-commit-id", "--name-only", "-z", "--no-renames"];
console.log("c1 names:", JSON.stringify(ok(out, [...FLAGS, c1])));
console.log("c2 names:", JSON.stringify(ok(out, [...FLAGS, c2])));

// merge commit first-parent diff
ok(src, ["checkout", "-q", "-b", "side", c1]);
writeFileSync(join(src, "g.txt"), "x <= y\n");
ok(src, ["add", "-A"]);
ok(src, ["commit", "-qm", "side"]);
ok(src, ["checkout", "-q", "main"]);
ok(src, ["merge", "-q", "--no-ff", "-m", "merge side", "side"], undefined, { GIT_EDITOR: "true" });
const merge = ok(src, ["rev-parse", "HEAD"]).trim();
const out2 = join(base, "copy2");
ok(base, ["clone", "--no-local", src, out2]);
console.log("merge names:", JSON.stringify(ok(out2, [...FLAGS, merge])));
console.log("merge first-parent diff:", ok(out2, ["diff", "--no-renames", "-U0", `${merge}^1`, merge, "--", "g.txt"]));

// three-arg cacheinfo
const content = ok(out, ["show", `${c2}:f.txt`]);
const blob = ok(out, ["hash-object", "-w", "--stdin"], Buffer.from(content.replace(">", "<"))).trim();
const idx = join(base, "idx");
ok(out, ["read-tree", `${c2}^{tree}`], undefined, { GIT_INDEX_FILE: idx });
const r3 = run(out, ["update-index", "--add", "--cacheinfo", "100644", blob, "f.txt"], undefined, { GIT_INDEX_FILE: idx });
console.log("three-arg cacheinfo:", r3.code, JSON.stringify(r3.err.trim()));
const tree = ok(out, ["write-tree"], undefined, { GIT_INDEX_FILE: idx }).trim();
console.log("tree diff:", ok(out, ["diff", "--no-renames", "-U0", `${c2}^{tree}`, tree]));
rmSync(base, { recursive: true, force: true });

// scratch4: comma form of --cacheinfo with a comma in the path
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

function ok(cwd: string, args: string[], stdin?: Buffer, env: Record<string, string> = {}) {
  const r = Bun.spawnSync(["git", ...args], { cwd, stdin: stdin ?? "ignore", stdout: "pipe", stderr: "pipe", env: { ...process.env, ...env } });
  if (r.exitCode !== 0) throw new Error(`git ${args.join(" ")}: ${r.stderr.toString()}`);
  return r.stdout.toString();
}

const base = mkdtempSync(join(tmpdir(), "f10scratch4-"));
const repo = join(base, "r");
mkdirSync(repo);
ok(repo, ["init", "-q", "-b", "main"]);
ok(repo, ["config", "user.email", "[REDACTED_EMAIL]"]);
ok(repo, ["config", "user.name", "T"]);
writeFileSync(join(repo, "we,ird name.txt"), "a < b\n");
ok(repo, ["add", "-A"]);
ok(repo, ["commit", "-qm", "c"]);
const sha = ok(repo, ["rev-parse", "HEAD"]).trim();
const blob = ok(repo, ["hash-object", "-w", "--stdin"], Buffer.from("a > b\n")).trim();
const idx = join(base, "idx");
ok(repo, ["read-tree", `${sha}^{tree}`], undefined, { GIT_INDEX_FILE: idx });
const r = Bun.spawnSync(["git", "update-index", "--add", "--cacheinfo", `100644,${blob},we,ird name.txt`], {
  cwd: repo,
  stdout: "pipe",
  stderr: "pipe",
  env: { ...process.env, GIT_INDEX_FILE: idx },
});
console.log("comma form exit:", r.exitCode, JSON.stringify(r.stderr.toString().trim()));
if (r.exitCode === 0) {
  const tree = ok(repo, ["write-tree"], undefined, { GIT_INDEX_FILE: idx }).trim();
  console.log(ok(repo, ["diff", "--no-renames", "-U0", `${sha}^{tree}`, tree]));
}
rmSync(base, { recursive: true, force: true });

