ok(src, ["init", "-q", "-b", "main"]);
ok(src, ["config", "user.email", "[REDACTED_EMAIL]"]);
ok(src, ["config", "user.name", "T"]);
writeFileSync(join(src, "a.js"), "if (count >= limit) { stop(); }\n");
ok(src, ["add", "-A"]);
ok(src, ["commit", "-qm", "add guard"]);
const sha = ok(src, ["rev-parse", "HEAD"]);

