const run = Bun.spawnSync(
  ["bun", "scripts/planted/plant.ts", "--source", src, "--out", join(base, "copy"), "--key", join(base, "key.json"), "--seed", "4", "--commit", sha],
  { cwd, stdout: "pipe", stderr: "pipe" },
);
